# Generated by Selenium IDE
# Test Case: Donor Functionality Test Suite (Post-Authentication)

import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestDonorFunctionality:

    def setup_method(self, method=None):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()   # Maximize window to prevent hidden elements
        self.wait = WebDriverWait(self.driver, 12)  # Explicit wait

        # Clean navigate to login
        self.driver.get("http://localhost:5173/login")
        self.driver.execute_script("localStorage.clear(); sessionStorage.clear();")
        self.driver.delete_all_cookies()
        self.driver.get("http://localhost:5173/login")
        time.sleep(0.8)

        # Click Donor role pill to auto-populate credentials
        try:
            pill = self.wait.until(
                EC.presence_of_element_located((By.XPATH, "//button[contains(@class, 'orphanage-role-btn') and contains(., 'Donor')]"))
            )
            self.driver.execute_script("arguments[0].click();", pill)
            time.sleep(0.4)
        except Exception:
            email_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "email")))
            email_field.clear()
            email_field.send_keys("eleanor.vance@orphanage.com")
            password_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "password")))
            password_field.clear()
            password_field.send_keys("Donor@123")

        # Submit login
        submit_btn = self.wait.until(
            EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))
        )
        self.driver.execute_script("arguments[0].scrollIntoView(true);", submit_btn)
        self.driver.execute_script("arguments[0].click();", submit_btn)

        self.wait.until(EC.url_contains("/donor-dashboard"))
        time.sleep(1)

    def teardown_method(self, method=None):
        self.driver.quit()

    def test_donor_dashboard_kpis(self):
        """1. Verify Donor KPI Stat Cards (Total Donated, Items, 80G Receipts)."""
        self.driver.get("http://localhost:5173/donor-dashboard")
        time.sleep(1.5)

        # Check stat cards presence
        stat_cards = self.wait.until(
            EC.presence_of_all_elements_located((By.CLASS_NAME, "stat-card"))
        )
        assert len(stat_cards) >= 3, f"Expected at least 3 stat cards, found {len(stat_cards)}"
        print(f"[PASS] Donor KPI Stat Cards verified ({len(stat_cards)} cards present).")

    def test_donor_contribution_filters(self):
        """2. Verify contribution filtering (Monetary Only, Items & In-Kind, All)."""
        self.driver.get("http://localhost:5173/donor-dashboard")
        time.sleep(1.5)

        # Locate Monetary Only filter button
        money_filter = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Money') or contains(., 'Monetary')]"))
        )
        self.driver.execute_script("arguments[0].click();", money_filter)
        time.sleep(0.5)
        print("[PASS] Filtered by Monetary donations.")

        # Locate All Contributions filter button
        all_filter = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'All')]"))
        )
        self.driver.execute_script("arguments[0].click();", all_filter)
        time.sleep(0.5)
        print("[PASS] Filtered back to All Contributions.")

    def test_donor_donation_history_table(self):
        """3. Verify donation history table renders with receipt columns."""
        self.driver.get("http://localhost:5173/donor-dashboard")
        time.sleep(1.5)

        table = self.wait.until(EC.presence_of_element_located((By.TAG_NAME, "table")))
        assert table is not None

        headers = self.driver.find_elements(By.CSS_SELECTOR, "table thead th")
        header_texts = [h.get_attribute("textContent").strip() for h in headers]
        assert any("Date" in h for h in header_texts), "Date column missing"
        assert any("Receipt" in h or "Ref" in h for h in header_texts), "Receipt column missing"
        print(f"[PASS] Donation history table verified with columns: {header_texts}")

    def test_donor_make_donation_modal(self):
        """4. Verify 'Donate Money (Razorpay)' button opens payment modal."""
        self.driver.get("http://localhost:5173/donor-dashboard")
        time.sleep(1.5)

        # Click Donate Money button
        donate_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Donate Money') or contains(., 'Razorpay')]"))
        )
        self.driver.execute_script("arguments[0].click();", donate_btn)
        time.sleep(1)

        # Verify modal overlay exists
        page_source = self.driver.page_source
        assert "Payment" in page_source or "Razorpay" in page_source or "Amount" in page_source, "Donation modal failed to open."
        print("[PASS] 'Donate Money' payment modal opened successfully.")

    def test_donor_donation_page_navigation(self):
        """5. Verify Donor can access the dedicated Donation portal page."""
        self.driver.get("http://localhost:5173/donation")
        time.sleep(1.5)

        assert "/donation" in self.driver.current_url
        page_body = self.driver.find_element(By.TAG_NAME, "body").text
        assert "Donation" in page_body or "₹" in page_body, "Donation page content missing."
        print("[PASS] Dedicated Donation page loaded successfully for Donor.")


if __name__ == "__main__":
    test = TestDonorFunctionality()
    test.setup_method()
    try:
        print("\n--- Running Donor Functionality Tests ---")
        test.test_donor_dashboard_kpis()
        test.test_donor_contribution_filters()
        test.test_donor_donation_history_table()
        test.test_donor_make_donation_modal()
        test.test_donor_donation_page_navigation()
        print("\n>>> ALL DONOR FUNCTIONALITY TESTS PASSED SUCCESSFULLY! <<<\n")
    finally:
        test.teardown_method()
